INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-development', 'development', 'Kunst- og kulturutvikling', '{"summary":"Vi vil utvikle [PROGRAM/RESIDENCY/NETTVERK] med base på gården i Rauma.","need":"Prosjektet svarer på [BEHOV] i det regionale kulturfeltet.","method":"Utviklingsløpet gjennomføres med [PARTNERE] over [PERIODE] og inkluderer [AKTIVITETER].","impact":"Resultatet skal være en varig modell for [PRODUKSJON/FORMIDLING/NETTVERK]."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-teft', 'teft', 'TEFT – lokal møteplass og kultur', '{"summary":"Gjennom frivillig innsats vil vi utvikle [TILTAK] på et småbruk i Rauma til en inkluderende kultur- og møteplass.","need":"Prosjektet tar vare på eksisterende ressurser og møter et lokalt behov for [MØTEPLASS/KULTURAKTIVITET].","method":"Midlene brukes konkret til [UTSTYR/TILTAK], mens [EGENINNSATS/ANNEN FINANSIERING] dekker resten.","impact":"Prosjektet skaper varig lokal verdi gjennom [AKTIVITET], [FRIVILLIGE] og [BRUKERE]."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-smil', 'smil', 'SMIL – kulturmiljø', '{"summary":"Vi søker støtte til å ivareta [STEINMUR/KULTURLANDSKAP] som del av gårdens historiske jordbruksmiljø.","need":"Elementet er skadet av [ÅRSAK] og står i fare for videre forfall.","method":"Arbeidet utføres med tradisjonell metode og tilpasses landskapet og gårdsmiljøet.","impact":"Tiltaket styrker kulturmiljø, landskapskvalitet og formidling av gårdens historie."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-local', 'local', 'Lokale kulturmidler', '{"summary":"[FORENING] søker støtte til [AKTIVITET] på gården i Rauma.","need":"Tiltaket gir et åpent og tilgjengelig kulturtilbud lokalt.","method":"Aktiviteten gjennomføres av frivillige i samarbeid med [PARTNERE].","impact":"Vi forventer [ANTALL] deltakere og vil dokumentere aktivitet og lokal effekt."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-business', 'business', 'Landbruksbasert næringsutvikling', '{"summary":"Vi vil utvikle en ny landbruksbasert virksomhet knyttet til [RETREAT/STUDIO/KULTURREISELIV] på gården.","need":"Konseptet utnytter eksisterende bygningsmasse og gårdens beliggenhet i Romsdalen.","method":"Investeringen omfatter [FASTE ANLEGG/UTSTYR] og bygger på dokumentert marked, prisstrategi og driftsbudsjett.","impact":"Prosjektet skal skape nye inntekter, økt bruk av gården og lokal verdiskaping."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-roof', 'roof', 'Ta et tak', '{"summary":"Vi søker støtte til å sikre og restaurere taket på [BYGG], en eldre del av gårdsmiljøet.","need":"Taket har [SKADE] og svikt vil føre til følgeskader i den historiske konstruksjonen.","method":"Arbeidet gjennomføres med [MATERIALER] og mest mulig bevaring av eksisterende konstruksjon.","impact":"Tiltaket sikrer bygningen for framtidig aktiv bruk."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
INSERT INTO application_templates (id, legacy_id, title, sections, provenance, created_at, updated_at) VALUES ('tmpl-community', 'community', 'Frivillighet og møteplass', '{"summary":"Vi vil skape en åpen møteplass for [MÅLGRUPPE] gjennom [AKTIVITET].","need":"Lokalsamfunnet har behov for [BEHOV].","method":"Prosjektet drives av frivillige med tydelige roller, samarbeidspartnere og aktivitetsplan.","impact":"Vi måler effekt gjennom deltakelse, frivilligtimer, brukerdager og videre aktivitet."}', 'legacy_mvp_2026_09_08', '2026-09-20T00:00:00.000Z', '2026-09-20T00:00:00.000Z') ON CONFLICT(id) DO UPDATE SET title = excluded.title, sections = excluded.sections, updated_at = excluded.updated_at WHERE application_templates.provenance = 'legacy_mvp_2026_09_08';
